const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const services=[{name:'Loc retwist',price:135,duration:165,description:'Shoulders and above · 2 hr 45 min'},{name:'Retwist + two-strand twists',price:155,duration:210,description:'Starting option · 3 hr 30 min'},{name:'Retwist + barrel twists',price:160,duration:150,description:'Starting option · 2 hr 30 min'},{name:'Starter locs',price:185,duration:180,description:'Shoulders and above · 3 hr'},{name:'Loc reconstruction',price:475,duration:270,description:'Starting option · 4 hr 30 min'},{name:'Consultation',price:50,duration:45,description:'Let’s talk about your loc journey · 45 min'}];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=dateKey(new Date());
const future=n=>{let d=new Date();d.setDate(d.getDate()+n);return dateKey(d)};
const pretty=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const clock=n=>`${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n<720?'AM':'PM'}`;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({clients:[{id:1,name:'Amara Williams',email:'amara@example.com',phone:'(206) 555-0101',service:1,last:future(-42),optin:true,notes:'Prefers two-strand twists. Shoulder-length locs. Ask about scalp sensitivity at next visit.'},{id:2,name:'Darius Jackson',email:'darius@example.com',phone:'(206) 555-0102',service:2,last:future(-28),optin:true,notes:'Barrel twist preference. Keeps sides tapered.'},{id:3,name:'Nia Thompson',email:'nia@example.com',phone:'(425) 555-0103',service:0,last:future(-62),optin:true,notes:'Maintenance visit due. Prefers weekday mornings.'},{id:4,name:'Jordan Brooks',email:'jordan@example.com',phone:'(206) 555-0104',service:3,last:future(-21),optin:false,notes:'Starter loc journey. Discuss washing routine.'},{id:5,name:'Imani Davis',email:'imani@example.com',phone:'(425) 555-0105',service:0,last:future(-49),optin:true,notes:'Interested in a new style for her next visit.'},{id:6,name:'Malik Reed',email:'malik@example.com',phone:'(206) 555-0106',service:5,last:future(-90),optin:true,notes:'Consultation completed. Follow up about starter locs.'}],appointments:[{id:1,clientId:1,service:1,date:today,time:540,status:'Confirmed'},{id:2,clientId:2,service:2,date:today,time:780,status:'Confirmed'},{id:3,clientId:4,service:5,date:today,time:960,status:'Confirmed'},{id:4,clientId:5,service:0,date:future(2),time:600,status:'Confirmed'}],campaigns:[],subscribers:[]});
let data;try{data=JSON.parse(localStorage.getItem('zae-demo-v1'))}catch{}if(!data?.clients||!data?.appointments)data=seed();
function save(){try{localStorage.setItem('zae-demo-v1',JSON.stringify(data))}catch{toast('This browser can’t save changes. Keep this tab open to continue.')}}
let bookingDraft={name:'',phone:'',email:'',consent:false,ack:false};
let currentPage='overview',admin=false,selectedService=0,bookingDate=future(1),bookingTime=null,bookingStep=1,selectedCampaign='retwist';
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function openDialog(id){$(id).showModal();document.documentElement.classList.add('dialog-open')}
$$('dialog').forEach(d=>d.addEventListener('close',()=>document.documentElement.classList.remove('dialog-open')));
$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#serviceList').innerHTML=services.map((s,i)=>`<div class="service"><div><strong>${s.name}</strong><p>${s.description}</p></div><span class="price">${money(s.price)}${i===5?'':'+'}</span><button data-service="${i}">Choose service ↗</button></div>`).join('');
$$('[data-book]').forEach(b=>b.onclick=()=>startBooking());$$('[data-service]').forEach(b=>b.onclick=()=>startBooking(+b.dataset.service));
$('#switchView').onclick=()=>{admin=!admin;$('#switchView').setAttribute('aria-pressed',String(admin));$('#studio').hidden=admin;$('#dashboard').hidden=!admin;$('#switchView').textContent=admin?'View client website ↗':'Explore Zae’s dashboard ↗';if(admin)renderAdmin();window.scrollTo(0,0)};
$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));function go(p){currentPage=p;renderAdmin();window.scrollTo(0,0)}
$('#resetDemo').onclick=()=>{data=seed();save();renderAdmin();toast('Sample clients and appointments restored.')};
$('#subscribe').onsubmit=e=>{e.preventDefault();const email=$('#subscriber').value.trim().toLowerCase();if(!data.subscribers.includes(email)){data.subscribers.push(email);save()}$('#subscribeResult').textContent='You’re on the demo list. No email was sent.';$('#subscribe').reset()};
function startBooking(i=0){bookingDraft={name:'',phone:'',email:'',consent:false,ack:false};selectedService=i;bookingDate=future(1);bookingTime=null;bookingStep=1;renderBooking();openDialog('#booking')}
function available(date,service){const dur=services[service].duration;let slots=[];for(let t=540;t+dur<=1140;t+=30){if(!data.appointments.some(a=>a.date===date&&a.status!=='Cancelled'&&t<a.time+services[a.service].duration&&t+dur>a.time)&&!(date===today&&t<=new Date().getHours()*60+new Date().getMinutes()))slots.push(t)}return slots}
function renderBooking(){const s=services[selectedService];$('#bookingContent').innerHTML=bookingStep===1?`<h2>Your next visit.</h2><ol class="booking-progress" aria-label="Booking progress"><li aria-current="step">Service & time</li><li>Your details</li></ol><p>Choose a service and a time that feels right.</p><div class="notice">Demo availability only. No payment is collected.</div><div class="fields"><div class="full"><label for="bookService">Service</label><select id="bookService">${services.map((s,i)=>`<option value="${i}" ${i===selectedService?'selected':''}>${s.name} · from ${money(s.price)}</option>`).join('')}</select></div><div class="full"><label for="bookDate">Date</label><input id="bookDate" type="date" min="${today}" value="${bookingDate}"></div></div><h3>Available times</h3><div id="slots" class="times" role="group" aria-label="Available appointment times"></div><p class="small">Sample studio hours: 9 AM–7 PM. Times shown in your device’s local time.</p><div class="dialog-actions"><span>From ${money(s.price)}</span><button class="solid" id="bookNext">Your details ↗</button></div><p class="error" id="bookError" role="alert"></p>`:`<h2>Make it yours.</h2><ol class="booking-progress" aria-label="Booking progress"><li>Service & time</li><li aria-current="step">Your details</li></ol><div class="booking-summary"><strong>${s.name}</strong>${pretty(bookingDate)} · ${clock(bookingTime)}<br>Starting service price ${money(s.price)}. No payment in this demo.</div><form id="bookingForm"><div class="fields"><div><label for="bookName">Full name</label><input id="bookName" value="${esc(bookingDraft.name)}" required autocomplete="name" maxlength="100"></div><div><label for="bookPhone">Phone</label><input id="bookPhone" value="${esc(bookingDraft.phone)}" required type="tel" autocomplete="tel" maxlength="40"></div><div class="full"><label for="bookEmail">Email</label><input id="bookEmail" value="${esc(bookingDraft.email)}" required type="email" autocomplete="email" maxlength="150"></div></div><label class="check"><input id="bookConsent" type="checkbox" ${bookingDraft.consent?'checked':''}> Send me offers, loc care tips, and new openings by email. I can unsubscribe anytime.</label><label class="check"><input id="bookAck" type="checkbox" ${bookingDraft.ack?'checked':''} required> I understand this creates a sample appointment only.</label><div class="dialog-actions"><button type="button" id="bookBack">Back</button><button class="solid">Confirm demo booking</button></div><p class="error" id="bookError" role="alert"></p></form>`;
if(bookingStep===1){drawSlots();$('#bookService').onchange=e=>{selectedService=+e.target.value;bookingTime=null;renderBooking()};$('#bookDate').onchange=e=>{bookingDate=e.target.value;bookingTime=null;drawSlots()};$('#bookNext').onclick=()=>{if(!bookingDate||bookingDate<today||bookingTime===null){$('#bookError').textContent='Choose a valid date and an available time to continue.';return}bookingStep=2;renderBooking();$('#bookName').focus()}}else{['#bookName','#bookPhone','#bookEmail','#bookConsent','#bookAck'].forEach(sel=>$(sel).oninput=()=>{bookingDraft={name:$('#bookName').value,phone:$('#bookPhone').value,email:$('#bookEmail').value,consent:$('#bookConsent').checked,ack:$('#bookAck').checked}});$('#bookBack').onclick=()=>{bookingStep=1;renderBooking();$('#bookService').focus()};$('#bookingForm').onsubmit=finishBooking}}
function drawSlots(){if(!bookingDate||bookingDate<today){$('#slots').innerHTML='<p>Choose today or a future date.</p>';return}const slots=available(bookingDate,selectedService);$('#slots').innerHTML=slots.length?slots.map(t=>`<button class="time ${bookingTime===t?'selected':''}" aria-pressed="${bookingTime===t}" data-time="${t}">${clock(t)}</button>`).join(''):'<p>No openings on this day. Try another date.</p>';$$('[data-time]').forEach(b=>b.onclick=()=>{bookingTime=+b.dataset.time;drawSlots()})}
function finishBooking(e){e.preventDefault();if(!available(bookingDate,selectedService).includes(bookingTime)){$('#bookError').textContent='That time is no longer available. Go back and choose another.';return}const email=$('#bookEmail').value.trim().toLowerCase();let client=data.clients.find(c=>c.email.toLowerCase()===email);if(!client){client={id:Date.now(),name:$('#bookName').value.trim(),email,phone:$('#bookPhone').value.trim(),service:selectedService,last:null,optin:$('#bookConsent').checked,notes:''};data.clients.push(client)}else if($('#bookConsent').checked)client.optin=true;data.appointments.push({id:Date.now(),clientId:client.id,service:selectedService,date:bookingDate,time:bookingTime,status:'Confirmed'});save();$('#bookingContent').innerHTML=`<div class="confirm-mark" aria-hidden="true"><svg width="42" height="42" viewBox="0 0 42 42"><path d="M8 21l9 9L35 11" fill="none" stroke="currentColor" stroke-width="3"/></svg></div><h2>Your demo visit is booked.</h2><p>See how it feels to book directly with Zae.</p><div class="booking-summary"><strong>${services[selectedService].name}</strong>${pretty(bookingDate)} at ${clock(bookingTime)}<br>${esc(client.name)}</div><p class="small">Saved on this device only. No appointment was made with Zae, no payment was taken, and no email was sent.</p><button class="solid" id="doneBooking">Back to the studio</button>`;$('#doneBooking').onclick=()=>{$('#booking').close();if(admin)renderAdmin()}}
function header(title,sub,action=''){return `<div class="admin-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function apptRows(rows){return rows.length?rows.map(a=>{const c=data.clients.find(c=>c.id===a.clientId);return `<div class="appt-row"><time>${clock(a.time)}</time><div><strong>${esc(c?.name||'Client')}</strong><span class="sub">${services[a.service].name}</span></div><button data-appt="${a.id}">Details</button></div>`}).join(''):'<p class="empty">No appointments here yet.</p>'}
function renderAdmin(){$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===currentPage);b.setAttribute('aria-current',b.dataset.page===currentPage?'page':'false')});const el=$('#adminContent');if(currentPage==='overview'){const rows=data.appointments.filter(a=>a.date===today&&a.status!=='Cancelled').sort((a,b)=>a.time-b.time);const revenue=rows.reduce((n,a)=>n+services[a.service].price,0);const due=audience('retwist');el.innerHTML=header('Studio overview',`${pretty(today)} · Sample studio day`,`<button class="solid" id="addBooking">New booking</button>`)+`<div class="stats"><div><p>Today’s appointments</p><strong>${rows.length}</strong><small>Confirmed & completed</small></div><div><p>Service value</p><strong>${money(revenue)}</strong><small>Starting prices · before fees</small></div><div><p>Client community</p><strong>${data.clients.length}</strong><small>${data.clients.filter(c=>c.optin).length} email subscribers</small></div></div><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>In the chair today</h2><button data-go="appointments">All appointments</button></div>${apptRows(rows)}</section><div class="rail"><section class="panel"><div class="panel-head"><h2>Time for a retwist</h2><button data-go="clients">View clients</button></div><p>${due.length} opted-in clients last visited 6+ weeks ago.</p>${due.slice(0,3).map(c=>`<div class="client-mini"><span class="avatar">${esc(c.name.split(' ').map(n=>n[0]).join(''))}</span><p>${esc(c.name)}<small>Last visit ${pretty(c.last)}</small></p></div>`).join('')}</section><section class="rail-callout"><h3>Bring them back to your chair.</h3><p>A personal reminder with a direct booking link.</p><button id="startRetwist">Preview retwist email ↗</button></section></div></div>`;$('#addBooking').onclick=()=>startBooking();$('#startRetwist').onclick=()=>{selectedCampaign='retwist';go('marketing')}}
else if(currentPage==='appointments'){el.innerHTML=header('Appointments','Manage sample bookings. Changes stay on this device.',`<button class="solid" id="addBooking">New booking</button>`)+`<div class="toolbar"><input type="date" id="apptDate" value="${today}" aria-label="Appointment date"><select id="apptStatus" aria-label="Appointment status"><option value="all">All statuses</option><option>Confirmed</option><option>Completed</option><option>Cancelled</option></select></div><section class="panel"><h2 id="apptTitle">${pretty(today)}</h2><div id="apptResults"></div></section>`;$('#addBooking').onclick=()=>startBooking();$('#apptDate').onchange=filterAppointments;$('#apptStatus').onchange=filterAppointments;filterAppointments()}
else if(currentPage==='clients'){el.innerHTML=header('Clients','Loc journeys, preferences, and conversations in one place.')+`<div class="toolbar"><input id="clientSearch" type="search" placeholder="Search name or email" aria-label="Search clients"><select id="clientFilter" aria-label="Client filter"><option value="all">All clients</option><option value="optin">Email subscribers</option><option value="due">Due for a visit</option></select></div><div class="table-wrap"><table><thead><tr><th>Client</th><th>Last visit</th><th>Preferred service</th><th>Marketing</th><th></th></tr></thead><tbody id="clientRows"></tbody></table></div><p class="small" id="clientCount"></p>`;$('#clientSearch').oninput=filterClients;$('#clientFilter').onchange=filterClients;filterClients()}
else renderMarketing();wireAdmin()}
function wireAdmin(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-appt]').forEach(b=>b.onclick=()=>appointmentDetail(+b.dataset.appt));$$('[data-client]').forEach(b=>b.onclick=()=>clientDetail(+b.dataset.client))}
function filterAppointments(){let date=$('#apptDate').value,status=$('#apptStatus').value;$('#apptTitle').textContent=date?pretty(date):'Choose a date';$('#apptResults').innerHTML=apptRows(data.appointments.filter(a=>a.date===date&&(status==='all'||a.status===status)).sort((a,b)=>a.time-b.time));wireAdmin()}
function audience(type){if(type==='opening')return data.clients.filter(c=>c.optin);const threshold=type==='return'?60:42;return data.clients.filter(c=>c.optin&&c.last&&(new Date(today+'T12:00:00')-new Date(c.last+'T12:00:00'))/86400000>=threshold&&!data.appointments.some(a=>a.clientId===c.id&&a.date>=today&&a.status==='Confirmed'))}
function filterClients(){const q=$('#clientSearch').value.toLowerCase(),f=$('#clientFilter').value;let rows=data.clients.filter(c=>(c.name+' '+c.email).toLowerCase().includes(q)&&(f==='all'||f==='optin'&&c.optin||f==='due'&&audience('retwist').some(x=>x.id===c.id)));$('#clientRows').innerHTML=rows.map(c=>`<tr><td data-label="Client">${esc(c.name)}<small>${esc(c.email)}</small></td><td data-label="Last visit">${c.last?pretty(c.last):'No past visit'}</td><td data-label="Service">${services[c.service].name}</td><td data-label="Email">${c.optin?'<span class="badge">Subscribed</span>':'Not subscribed'}</td><td><button data-client="${c.id}">Open profile</button></td></tr>`).join('')||'<tr><td colspan="5">No clients match your search.</td></tr>';$('#clientCount').textContent=`${rows.length} ${rows.length===1?'client':'clients'} · Sample records`;wireAdmin()}
function clientDetail(id){const c=data.clients.find(c=>c.id===id),visits=data.appointments.filter(a=>a.clientId===id);$('#detailContent').innerHTML=`<h2>${esc(c.name)}</h2><p>${esc(c.email)}<br>${esc(c.phone)}</p><div class="profile-summary"><p>Preferred service<strong>${services[c.service].name}</strong></p><p>Email promotions<strong>${c.optin?'Subscribed':'Not subscribed'}</strong></p></div><div class="profile-notes"><label for="clientNotes">Hair & care notes</label><textarea id="clientNotes" maxlength="3000">${esc(c.notes)}</textarea><button class="solid" id="saveNotes">Save notes</button></div><h3>Appointment history</h3>${visits.length?visits.map(a=>`<p>${pretty(a.date)} · ${clock(a.time)}<br>${services[a.service].name} · ${a.status}</p>`).join(''):'<p>No bookings in this demo yet.</p>'}<p class="small">Fictional client profile. Notes are saved on this device.</p>`;$('#saveNotes').onclick=()=>{c.notes=$('#clientNotes').value;save();toast('Client notes saved on this device.')};openDialog('#detail')}
function appointmentDetail(id){const a=data.appointments.find(a=>a.id===id),c=data.clients.find(c=>c.id===a.clientId);$('#detailContent').innerHTML=`<h2>${esc(c.name)}</h2><div class="booking-summary"><strong>${services[a.service].name}</strong>${pretty(a.date)} · ${clock(a.time)}<br>Starting price ${money(services[a.service].price)}<br>Status: ${a.status}</div><p class="small">Demo appointment. Changes don’t contact the client.</p>${a.status==='Confirmed'?`<div class="row-actions"><button id="completeAppt">Mark completed</button><button id="rescheduleAppt">Reschedule</button><button id="cancelAppt">Cancel appointment</button></div>`:''}`;if(a.status==='Confirmed'){$('#completeAppt').onclick=()=>{a.status='Completed';c.last=a.date;save();$('#detail').close();renderAdmin();toast('Sample appointment marked completed.')};$('#cancelAppt').onclick=()=>{$('#detailContent').innerHTML=`<h2>Cancel this booking?</h2><p>${esc(c.name)} · ${pretty(a.date)} at ${clock(a.time)}</p><p>Only this sample booking will change.</p><button class="solid" id="confirmCancel">Cancel sample booking</button>`;$('#confirmCancel').onclick=()=>{a.status='Cancelled';save();$('#detail').close();renderAdmin();toast('Sample booking cancelled. The time is available again.')}};$('#rescheduleAppt').onclick=()=>{$('#detailContent').innerHTML=`<h2>Find a new time.</h2><label for="rescheduleDate">New date</label><input id="rescheduleDate" type="date" min="${today}" value="${future(1)}"><label for="rescheduleTime" style="margin-top:20px">Available time</label><select id="rescheduleTime"></select><button class="solid" id="saveReschedule" style="margin-top:24px">Save new time</button><p class="error" id="rescheduleError" role="alert"></p>`;const fill=()=>{const slots=available($('#rescheduleDate').value,a.service);$('#rescheduleTime').innerHTML=slots.length?slots.map(t=>`<option value="${t}">${clock(t)}</option>`).join(''):'<option value="">No openings</option>'};$('#rescheduleDate').onchange=fill;fill();$('#saveReschedule').onclick=()=>{let d=$('#rescheduleDate').value,t=Number($('#rescheduleTime').value);if(!d||d<today||!$('#rescheduleTime').value||!available(d,a.service).includes(t)){$('#rescheduleError').textContent='Choose an available future date and time.';return}a.date=d;a.time=t;save();$('#detail').close();renderAdmin();toast('Sample booking rescheduled.')}}}openDialog('#detail')}
const templates={retwist:{label:'Retwist reminder',subject:'Your next retwist is calling',headline:'A little care for your roots.',body:'It’s been a little while since your last visit. Let’s give your locs some love and find a time for your next retwist. Your chair is waiting.',audience:'Opted-in clients · 6+ weeks since last visit · no upcoming booking'},return:{label:'Reconnect',subject:'We’d love to see you back, {{first_name}}',headline:'Your chair is still here.',body:'However your loc journey is looking, there’s always room for your next chapter. Come through for a refresh, a new style, or a conversation about what’s next.',audience:'Opted-in clients · 60+ days since last visit · no upcoming booking'},opening:{label:'New openings',subject:'A little time just opened up at Zae Locs',headline:'Make some time for you.',body:'There’s room on the calendar for a little loc care. Take a look at the available times and choose your next visit. See you in the chair.',audience:'All opted-in clients'}};
function renderMarketing(){const t=templates[selectedCampaign];$('#adminContent').innerHTML=header('Email & marketing','Stay close to your clients, between visits.')+`<div class="campaign-types">${Object.entries(templates).map(([id,v])=>`<button data-campaign="${id}" class="${id===selectedCampaign?'active':''}">${v.label}</button>`).join('')}</div><div class="marketing-grid"><section class="panel composer"><h2>Make it personal.</h2><label for="emailAudience">Audience</label><select id="emailAudience"><option value="${selectedCampaign}">${t.audience}</option></select><p class="small">${audience(selectedCampaign).length} eligible sample clients · unsubscribed clients excluded</p><label for="emailSubject">Subject line</label><input id="emailSubject" value="${esc(t.subject)}" maxlength="150"><label for="emailHeadline">Email headline</label><input id="emailHeadline" value="${esc(t.headline)}" maxlength="100"><label for="emailBody">Message</label><textarea id="emailBody" maxlength="5000">${esc(t.body)}</textarea><button class="solid" id="reviewEmail">Review demo campaign ↗</button><p class="small">Preview only. No emails are sent.</p></section><section class="panel"><h2>Email preview</h2><p id="previewSubject"></p><div class="email-preview"><div class="email-brand">ZAE LOCS</div><h3 id="previewHeadline"></h3><p id="previewGreeting"></p><p id="previewBody"></p><button class="email-cta" id="previewBooking">Book your visit ↗</button><p>With care,<br>Zae</p><p class="email-foot">Zae Locs · 811 N Landing Way B, Suite 31, Renton, WA 98057<br>You’re receiving this because you opted in to studio emails.<br><u>Unsubscribe</u> · <u>Email preferences</u></p></div></section></div><section class="panel campaign-history"><h2>Demo campaign history</h2>${data.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Audience</th><th>State</th><th>Created</th></tr></thead><tbody>${data.campaigns.map(c=>`<tr><td data-label="Campaign">${esc(c.subject)}</td><td data-label="Audience">${c.count} sample clients</td><td data-label="Status"><span class="badge">Demo saved · not sent</span></td><td data-label="Created">${pretty(c.date)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Your saved demo campaigns will appear here.</p>'}</section>`;$$('[data-campaign]').forEach(b=>b.onclick=()=>{selectedCampaign=b.dataset.campaign;renderMarketing()});['#emailSubject','#emailHeadline','#emailBody'].forEach(s=>$(s).oninput=updatePreview);updatePreview();$('#previewBooking').onclick=()=>startBooking();$('#reviewEmail').onclick=reviewEmail}
function updatePreview(){const c=audience(selectedCampaign)[0],first=c?c.name.split(' ')[0]:'friend';$('#previewSubject').textContent=$('#emailSubject').value.replaceAll('{{first_name}}',first);$('#previewHeadline').textContent=$('#emailHeadline').value;$('#previewGreeting').textContent=`Hey ${first},`;$('#previewBody').textContent=$('#emailBody').value;$('#previewBody').style.whiteSpace='pre-wrap'}
function reviewEmail(){const recipients=audience(selectedCampaign);if(!$('#emailSubject').value.trim()||!$('#emailBody').value.trim()){toast('Add a subject and message before reviewing.');return}$('#detailContent').innerHTML=`<h2>Ready for a preview?</h2><p><strong>${esc($('#emailSubject').value)}</strong></p><p>${recipients.length} eligible sample clients</p>${recipients.map(c=>`<p class="small">${esc(c.name)} · ${esc(c.email)}</p>`).join('')}<div class="notice">This saves a demo campaign only. No emails are sent and no performance results are invented.</div><button class="solid" id="saveCampaign" ${recipients.length?'':'disabled'}>Save demo campaign</button>`;$('#saveCampaign').onclick=()=>{data.campaigns.unshift({subject:$('#emailSubject').value,count:recipients.length,date:today});save();$('#detail').close();renderMarketing();toast('Demo campaign saved. No emails sent.')};openDialog('#detail')}
console.assert(services.every(s=>s.price>0&&s.duration>0),'Service prices and durations must be positive');

